import * as monaco from 'monaco-editor'

export function defineThemes(): void {
  monaco.editor.defineTheme('ide-dark', {
    base: 'vs-dark',
    inherit: true,
    rules: [],
    colors: { 'editor.background': '#0b1220' }
  })
  monaco.editor.defineTheme('ide-light', {
    base: 'vs',
    inherit: true,
    rules: [],
    colors: { 'editor.background': '#ffffff' }
  })
}
